def read_ints():
    return list(map(int, input().split()))

G, N, M = read_ints()
mutation_table = [[] for _ in range(G)]

for _ in range(N):
    a, k, *genes = read_ints()
    mutation_table[a].append((k, genes))

antibodies = []
for _ in range(M):
    l, *sequence = read_ints()
    antibodies.append(sequence)

def generate_viruses(start_gene):
    queue = [(start_gene, [start_gene])]
    visited = set()
    while queue:
        current_gene, virus = queue.pop(0)
        if (current_gene, tuple(virus)) in visited:
            continue
        visited.add((current_gene, tuple(virus)))
        for k, genes in mutation_table[current_gene]:
            new_virus = virus + genes
            queue.append((genes[0], new_virus))
            if len(set(new_virus)) == 2:
                yield new_virus

